export const languages={en:'English',zh:'中文',fr:'Français'};
let current='en';try{const v=localStorage.getItem('or-language');if(v in languages)current=v}catch{}
export function language(){return current}
export function setLanguage(v){if(!(v in languages))return;current=v;try{localStorage.setItem('or-language',v)}catch{}document.documentElement.lang=v==='zh'?'zh-CN':v}
export const pick=(en,zh,fr)=>({en,zh,fr}[current]||en);
