export function t(key){const row=text[key];return row?row[{en:0,zh:1,fr:2}[current]]:key}
export function translatedQuestion(q,translations){return language()==='en'?q:{...q,...translations[q.id]?.[language()]}}
export function chapterTitle(ch,translations){return language()==='en'?ch.title:translations[ch.id]?.[language()]||ch.title}
export function escapeHTML(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
setLanguage(current);
